def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'
    if n == 99:
        return 'D'

    opp_coops = 0
    for h in history:
        if h[1] == 'C':
            opp_coops += 1
    opp_defects = n - opp_coops

    last_me, last_opp = history[-1]

    if opp_defects == 0 and n >= 5:
        return 'D'

    if last_opp == 'D' and last_me == 'C':
        if opp_coops / n > 0.7 and n > 5:
            return 'C'
        return 'D'
    if last_opp == 'C' and last_me == 'D':
        return 'C'
    if opp_coops / n > 0.85:
        return 'C'
    if opp_coops / n < 0.3:
        return 'D'

    recent_len = min(10, n)
    recent_opp_coops = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'C':
            recent_opp_coops += 1
    recent_rate = recent_opp_coops / recent_len
    overall_rate = opp_coops / n

    if recent_len >= 5:
        if recent_rate < overall_rate - 0.3:
            return 'D'
        if recent_rate > overall_rate + 0.3:
            return 'C'

    if n > 80:
        if opp_coops / n < 0.5:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if rng.random() < 0.1 and opp_coops / n > 0.5:
            return 'C'
        return 'D'

    return 'C'
